input.command:
export EDITOR=/tmp/labs/timeflow/bin/setstatus
STATES="pending active paused deferred delegated recurring resolved template"
for src in pending active paused resolved template; do
  for dst in $STATES; do
    L=/tmp/labs/timeflow/m_${src}_${dst}
    rm -rf $L; mkdir -p $L; git -C $L init -q; git -C $L config user.email t@t; git -C $L config user.name T
    export DSTASK_GIT_REPO=$L
    case $src in
      pending) /workspace/executable add t >/dev/null 2>&1;;
      active) /workspace/executable add t >/dev/null 2>&1; /workspace/executable 1 start >/dev/null 2>&1;;
      paused) /workspace/executable add t >/dev/null 2>&1; /workspace/executable 1 start >/dev/null 2>&1; /workspace/executable 1 stop >/dev/null 2>&1;;
      resolved) /workspace/executable log t >/dev/null 2>&1;;
      template) /workspace/executable template t >/dev/null 2>&1;;
    esac
    out=$(STATUSVAL="$dst" /workspace/executable 1 edit 2>&1 | sed -e 's/\x1b\[[0-9;]*m//g' | tr '\n' '|'); rc=$?
    printf '%-9s -> %-9s rc=%s  %s\n' "$src" "$dst" "$rc" "$(echo "$out" | cut -c1-90)"
  done
done
